mapper.sql:
p.deleted_at IS NULL
AND p.name LIKE CONCAT('%',#{query.name},'%')

AND s.primary_country_iso2 IS NULL
AND s.primary_country_iso2=#{query.countryIso2}
AND s.continent=#{query.continent}
AND p.last_used_at IS NOT NULL
AND p.created_at >= #{query.createdFrom}
AND p.created_at <= #{query.createdTo}
AND s.unused_count > 0

mapper.select:
SELECT p.* FROM group_data_package p JOIN group_data_package_stat s
ON s.package_id=p.id AND s.tenant_id=p.tenant_id WHERE 
ORDER BY p.id DESC LIMIT #{query.pageSize} OFFSET #{query.offset}
